<section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari penilaian</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Nama atau NIK koperasi"></label><label><span>Status</span><select name="status"><option value="">Semua</option><option value="draft" <?= $p['status']==='draft'?'selected':'' ?>>Draf</option><option value="submitted" <?= $p['status']==='submitted'?'selected':'' ?>>Terkunci</option><option value="reviewed" <?= $p['status']==='reviewed'?'selected':'' ?>>Ditinjau</option><option value="withdrawn" <?= $p['status']==='withdrawn'?'selected':'' ?>>Dibatalkan</option></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Koperasi</th><th>Jalur KKPKK</th><th>Tahun buku</th><th>Revisi</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td><strong><?= h($r['cooperative_name']) ?></strong></td><td><?= h($r['form_name']) ?></td><td><?= h($r['fiscal_year']) ?></td><td class="mono"><?= h($r['revision_no']) ?></td><td><span class="pill <?= $r['locked_at']?'pill-blue':'pill-muted' ?>"><?= $r['status']==='withdrawn'?'Dibatalkan':($r['locked_at']?'Terkunci':'Draf') ?></span></td><td><a class="row-link" href="<?= site_url('admin/penilaian/'.$r['id']) ?>">Buka →</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="6" class="empty-cell">Belum ada penilaian yang sesuai pencarian.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
